{
 "research_concepts": [
  "Pick and Roll (PNR) failure",
  "Pull-up shot",
  "Offensive counter-strategy",
  "Play-type efficiency",
  "Conditional offensive performance"
 ],
 "methodological_questions": [
  "How to define 'PNR fail' from play-by-play or derived play-type data?",
  "How to identify 'PULL_UP' shots and their outcomes?",
  "How to measure 'lift' (change in offensive efficiency) in percentage points?",
  "What is the appropriate 'unit' of analysis (player, team, lineup) for 'league-wide' assessment?",
  "How to establish a conditional relationship between PNR failure and subsequent PULL_UP efficiency?",
  "What statistical methods are suitable for testing proportions of units and median lift across the league?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPA-063",
   "status_as_recorded": "supported",
   "finding": "Pre-game PT PPP ranking from training data correlates with actual efficiency ranking in held-out games. Median rho +0.539 (IQR +0.245 to +0.750); 62.4% rho>0.4; 88.4% rho>0; 10.5% rho<0. Top-3 median hit 100%; >=2/3 hits 78.9%; median lift +0.4261 PPP; 90.8% positive lift. Bottom-3 median suppression 66.7%."
  },
  {
   "id": "FAM:SF-PAP-096",
   "status_as_recorded": "artifact",
   "finding": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20"
  },
  {
   "id": "FAM:SF-APPS-058",
   "status_as_recorded": "untestable",
   "finding": "DET: 67 on-ball HC poss, 10 labeled (14.9%) ? DROP n=5 PPP=1.20, ICE_CANDIDATE n=5 PPP=0.80, OTHER n=57 PPP=1.42. ORL: 60 poss, 2 labeled (3.3%). switches_on unpopulated."
  },
  {
   "id": "FAM:SF-APPM-058",
   "status_as_recorded": "not a hypothesis test",
   "finding": "2024-25 shot-level PNR share of half-court shots ranges from OKC 7.567% (498/6581) and BOS 7.854% to IND 13.824% (856/6192) and NYK 11.959%. ATL 11.361%, DEN 11.404%, PHX 10.232% (bh 7.050 / roll 3.181)."
  },
  {
   "id": "FAM:SF-APPS-010",
   "status_as_recorded": "inconclusive",
   "finding": "DRIVE 0.889 -> 0.949 (+0.060); CUT +0.114; PNR +0.087; PULL_UP -0.077; POST_UP -0.032."
  },
  {
   "id": "FAM:SF-CHT-020",
   "status_as_recorded": "inconclusive",
   "finding": "T3: no PPP lift, negative mix-carry; did not replicate the in-game adapter PPP lift at Game N+1. Handoff: do not cite ~92.6% or ~96% calibrated numbers for SQ3."
  },
  {
   "id": "FAM:SF-APPA-066",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Team-PT lifts are small (ORL vs DET PNR +1.2pp; POR vs SAS all PT lifts negative, e.g. PNR -4.1pp) while player-channel lifts are large on small n (Banchero on Huerter SPOT_UP +8.4pp, n_def=17 / n_off=54; Dort on Coffey [cut; read_family for the full text]"
  },
  {
   "id": "FAM:SF-APPM-001",
   "status_as_recorded": "supported",
   "finding": "Raw gap aligned-deviated +5.18 ORtg; strength-controlled gap +3.27 ORtg (+0.0193 vs -0.0134 PPP residual). Model regret median +25.94 ORtg (non-negative by construction)."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPS-058",
   "what_failed": "Attempting to label on-ball defensive coverages (DROP/ICE/SWITCH) at usable rates from NBA matchup/PBP fields.",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:label_or_classification_error; LIM:small_sample; Confident label rates 14.9% and 3.3%; NBA matchups feed did not populate switches_on."
  },
  {
   "id": "FAM:SF-PAP-096",
   "what_failed": "Using possession-level play types from PBP containing an 'assisted' flag that was only present on makes.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); assisted flag on makes only produced SPOT_UP 2.83 PPP"
  },
  {
   "id": "FAM:SF-APPS-010",
   "what_failed": "Observational study of play-type PPP change across playoff series game buckets without clear signal or CIs.",
   "why": "E_unclear (mechanism unclear from the records); LIM:selection_or_regression_to_the_mean; 'NO CLEAR SIGNAL - DRIVE PPP is stable or improves across the series'; observational with selection caveats."
  },
  {
   "id": "FAM:SF-CHT-020",
   "what_failed": "Testing in-game adapter PPP lift carryover to Game N+1.",
   "why": "B_powered_null (adequately powered null result); Cross-game offensive carryover is null; in-game lift does not replicate at Game N+1."
  },
  {
   "id": "FAM:SF-APPA-066",
   "what_failed": "Decomposing TOV_FORCE matchup into defender x initiator x PT channels to find positive matchup lift.",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:insufficient_exposure; Player-channel n often 15-28 defensive possessions; primary_defender attribution includes helper steals; no holdout or game-outcome check."
  }
 ],
 "evidence_establishes": [
  "Play-type efficiency can be measured and is generally predictive of actual performance (FAM:SF-APPA-063, FAM:SF-APPM-001).",
  "PNR is a quantifiable and significant play type (FAM:SF-APPM-058).",
  "Derived play-type data can suffer from LABEL_ERROR if not carefully constructed (FAM:SF-PAP-096).",
  "Attempting to label granular defensive schemes (like DROP/ICE/SWITCH) directly from PBP data is likely untestable due to low label rates and data sparsity (FAM:SF-APPS-058).",
  "Player-level interaction effects often suffer from EXPOSURE_SPARSITY (FAM:SF-APPA-066).",
  "Cross-game carryover of in-game offensive adjustments is not supported (FAM:SF-CHT-020)."
 ],
 "evidence_does_not_establish": [
  "A reliable method for identifying 'PNR fail' from available data, especially in a way that implies a specific defensive counter-strategy.",
  "Whether PULL_UP shots are a specific, league-wide counter to PNR failure, or if such a conditional relationship can be robustly identified.",
  "The specific 'lift' (PPP change) associated with PULL_UP shots after PNR failure.",
  "What constitutes an appropriate 'unit' (player, team, lineup) for assessing 'league-wide' lift in this conditional context without suffering from sparsity issues."
 ],
 "own_inferences": [
  "The core challenge is defining 'PNR fail' in a way that is measurable from the data and truly represents a failure that prompts a counter, rather than just a low-efficiency PNR possession.",
  "A simple definition of 'PNR fail' as low PPP on PNR possessions risks confounding the 'failure' with general offensive inefficiency, making it difficult to isolate a specific counter-strategy.",
  "The term 'counter' implies intentionality or adaptation, which is difficult to establish through observational data alone without a clear causal model.",
  "The 'unit' of analysis (player, team, lineup) will significantly impact sample size and the interpretation of 'league-wide'. Player-level analysis is likely to suffer from sparsity."
 ],
 "uncertainties": [
  "The precise definition and measurability of 'PNR fail' from the available data.",
  "The appropriate baseline for calculating 'lift' for PULL_UP shots following a 'PNR fail'.",
  "Whether the observed correlation, if any, between PNR failure and PULL_UP efficiency represents a true counter-strategy or merely a common sequence of events or a reaction to general defensive pressure.",
  "The impact of defensive scheme variation on PNR outcomes and subsequent PULL_UP attempts, given the difficulty in labeling schemes.",
  "The exact mechanism by which a PNR 'fails' and why a PULL_UP would be the specific counter."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence, particularly FAM:SF-APPS-058, strongly suggests that directly identifying defensive schemes or specific types of 'PNR failure' from raw PBP data is untestable due to severe label sparsity and error. This makes the core premise of the research question – identifying a conditional counter to 'PNR fail' – highly problematic. Furthermore, FAM:SF-APPA-066 highlights the risk of EXPOSURE_SPARSITY for granular player-level analysis, which would be relevant if 'units' are individual players. This evidence shifted the decision from 'proceed' or 'proceed_with_changes' to 'do_not_proceed' because the foundational concept of 'PNR fail' is not robustly measurable from the data."
 },
 "testability": {
  "p_testable": 0.1,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "The definition of 'PNR fail' is highly susceptible to label error or is untestable with the available data, as direct defensive scheme identification is shown to be largely unfeasible (FAM:SF-APPS-058). A proxy for 'PNR fail' (e.g., low PPP PNR possessions) would be a derived label with unclear reliability as a true 'failure' state."
   },
   {
    "code": "CONFOUNDING",
    "text": "Any observed relationship between 'PNR fail' (if proxied by low PPP) and subsequent PULL_UP efficiency could be confounded by general defensive pressure, shot clock situations, or other factors not directly related to a specific counter-strategy. Without a clear definition of 'PNR fail' that isolates a specific defensive action, it's hard to attribute PULL_UPs as a 'counter'."
   },
   {
    "code": "EXPOSURE_SPARSITY",
    "text": "If 'units' are defined at a granular level (e.g., individual players or specific lineups), there will likely be insufficient samples for 'PNR fail' followed by 'PULL_UP' sequences to robustly calculate 'lift' for 70% of units, as evidenced by FAM:SF-APPA-066 for player-channel analysis."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [],
  "summary": "No prior work directly addressed the question of PULL_UP shots as a league-wide counter to PNR failure. Related studies examined play-type efficiency, PNR rates, and the difficulty of labeling defensive schemes, but not the specific conditional relationship and 'lift' proposed."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "Defining 'PNR fail' is challenging. If it's based on low PPP, it might conflate PNR failure with general offensive inefficiency or poor execution, rather than a specific defensive success that prompts a counter. If it attempts to infer specific defensive coverages, historical evidence (FAM:SF-APPS-058) shows this is largely untestable due to low label rates."
  },
  {
   "code": "CONFOUNDING",
   "text": "The relationship between 'PNR fail' and subsequent 'PULL_UP' could be confounded by factors like shot clock pressure, general defensive intensity, or player skill, rather than a specific strategic counter. It's difficult to isolate a true 'counter' effect from other in-game dynamics."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "If 'units' are individual players or specific lineup combinations, the number of observed sequences of 'PNR fail' followed by a 'PULL_UP' might be too low to achieve statistical power for 70% of units, as suggested by FAM:SF-APPA-066 regarding granular player-channel analysis."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "If 'PNR fail' is defined based on the outcome of the PNR possession (e.g., turnover, missed shot, low PPP), this could introduce circularity or bias when trying to measure the 'lift' of a subsequent PULL_UP, as the 'failure' is already an outcome."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "Assessing 'lift > 0' in '>=70% of units' and 'median lift > 2pp' across potentially many units (players, teams) introduces multiple testing concerns if not properly adjusted for."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.1,
  "untestable": 0.7,
  "artifact": 0.1,
  "uncertain": 0.05
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The difference in Points Per Possession (PPP) for PULL_UP shots immediately following a 'PNR fail' event, compared to a suitable baseline for PULL_UP shots, aggregated to specified units (e.g., team-season).",
  "unit": "Team-season, to mitigate exposure sparsity and ensure 'league-wide' applicability for initial exploratory analysis.",
  "sample": "All NBA 2022-23, 2023-24, 2024-25, and 2025-26 (complete regular season and playoffs) possessions. Identify PNR possessions using derived play-type data. Identify PULL_UP shots using play-by-play shot distance and action type.",
  "power": "Not applicable given the decision to not proceed, but a minimum of 50 PNR fail -> PULL_UP sequences per team-season unit would be a starting point for any meaningful analysis.",
  "controls": "For a descriptive analysis, control for shot clock situation, game score, and opponent strength. For a causal inference, consider propensity score matching or regression discontinuity if a clear threshold for 'PNR fail' could be established.",
  "falsification": "Examine the PPP of PULL_UP shots following 'successful' PNR possessions. If PULL_UPs are a general counter, their efficiency should not be uniquely higher after 'PNR fail'. Also, investigate if other play types show similar 'lift' after PNR fail.",
  "multiplicity": "Not applicable given the decision to not proceed. If proceeding, adjustments (e.g., Benjamini-Hochberg) would be required for multiple comparisons across units.",
  "decision_rule": "Not applicable given the decision to not proceed. The original decision rule was: 'lift>0 in >=70% of units with median lift>2pp'.",
  "data_version": "NBA 2022-23 to 2025-26 regular season and playoffs complete data."
 }
}

